// swift-tools-version: 5.9
import PackageDescription

// Resolve the Rust target directory relative to this package.
// build-swiftui.sh copies headers into Sources/rover_swiftFFI and
// rover_swift.swift into Sources/RoverCore before this package is built.
let package = Package(
    name: "RoverSwiftUI",
    platforms: [.macOS(.v14)],
    products: [
        .executable(name: "RoverApp", targets: ["RoverApp"]),
    ],
    targets: [
        // ── C FFI module (generated by UniFFI) ───────────────────────────
        // Headers are copied here by build-swiftui.sh.
        // build-swiftui.sh copies librover_swift.dylib into lib/ before the
        // Swift package is built, so the path is stable and package-relative.
        .target(
            name: "rover_swiftFFI",
            path: "Sources/rover_swiftFFI",
            publicHeadersPath: ".",
            linkerSettings: [
                .unsafeFlags(["-L", "lib"]),
                .linkedLibrary("rover_swift"),
            ]
        ),

        // ── Swift bindings + plugin protocol ─────────────────────────────
        // rover_swift.swift (generated) lives here alongside Plugin.swift etc.
        .target(
            name: "RoverCore",
            dependencies: ["rover_swiftFFI"],
            path: "Sources/RoverCore"
        ),

        // ── Native Swift plugins ─────────────────────────────────────────
        .target(
            name: "RoverPlugins",
            dependencies: ["RoverCore"],
            path: "Sources/RoverPlugins"
        ),

        // ── SwiftUI app ──────────────────────────────────────────────────
        .executableTarget(
            name: "RoverApp",
            dependencies: ["RoverCore", "RoverPlugins"],
            path: "Sources/RoverApp"
        ),
    ]
)
